/* metric:cm_elevate_applications_on_hold total */ SELECT COUNT(DISTINCT request_id) FILTER (WHERE data_verified = 'On Hold') AS applications_on_hold
FROM curated.v_cm_elevate
WHERE UPPER(lgd_district) = 'EAST KHASI HILLS'

SELECT COUNT(DISTINCT beneficiary_key) AS beneficiaries
FROM curated.v_focus_plus
WHERE lgd_district = 'RI BHOI';

/* metric:mgnrega_employment_generated total */ SELECT SUM(person_days) AS employment_generated
FROM curated.v_employment
WHERE UPPER(lgd_district) = 'RI BHOI' AND year_key = 2023

